function offerHTML(h){if(['service','guide'].includes(h.assistance?.intent?.responseMode)||h.assistance?.tasks?.length>1)return ''; const verifiedKinds=new Set((window.TravelServiceUI?.answerRows?.(h)||h.assistance?.services||[]).filter(row=>{const source=TravelLibrary.get(row.sourceId);return row.status!=='provider-search'&&source&&TravelLibrary.current(source)&&!source.publicationHash;}).map(row=>row.kind));if(['metro','nearby','restaurant'].includes(h.assistance?.intent?.kind)||TravelDiscovery.reply(h.text,{...state,history:state.history.slice(0,state.history.indexOf(h)+1)},TravelLibrary.records)?.places?.length)return '';const lang=h.language||state.language,zh=lang==='zh';return TravelTools.offers(h,lang).filter(group=>group.kind!=='flight'&&(group.kind!=='rail'||/amtrak/.test(group.url))&&!verifiedKinds.has(group.kind)).map(group=>'<section class="offer-group" data-metric-kind="'+esc(group.kind)+'" data-metric-item="'+esc(group.kind)+'-'+h.revision+'"><div class="offer-heading"><strong>'+esc(group.title)+'</strong><span class="demo-tag">'+(zh?'模拟推荐':'Sample offers')+'</span></div><p class="offer-warning">'+esc(group.disclaimer)+'</p><div class="offer-grid">'+group.items.map(item=>'<article class="offer-card"><strong>'+esc(item.name)+'</strong><div class="route">'+esc(item.route)+'</div><div class="details">'+esc(item.detail)+'</div><div class="price">'+esc(item.price)+'</div></article>').join('')+'</div><a class="offer-link" data-product-kind="'+esc(group.kind)+'" data-product-item="'+esc(group.kind)+'-'+h.revision+'" href="'+esc(group.url)+'" target="_blank" rel="noopener noreferrer">'+(zh?'去平台查询真实结果 ↗':'Check real options on provider ↗')+'</a></section>').join('');}
